$ErrorActionPreference = 'Stop'

# Автоматически исправляет все 13 замечаний use_build_context_synchronously,
# форматирует проект, запускает analyze/test и отправляет исправления в GitHub.

$Root = Split-Path -Parent $MyInvocation.MyCommand.Path
Set-Location $Root

if (-not (Test-Path (Join-Path $Root 'pubspec.yaml'))) {
  throw 'Положи этот файл в корень Flutter-проекта рядом с pubspec.yaml и запусти ещё раз.'
}

$Timestamp = Get-Date -Format 'yyyyMMdd_HHmmss'
$BackupRoot = Join-Path $env:TEMP "pr6_fix_backup_$Timestamp"
New-Item -ItemType Directory -Force -Path $BackupRoot | Out-Null

$Payload = @{
  'lib/screens/animal_form_screen.dart' = ''
  'lib/screens/animal_list_screen.dart' = ''
  'lib/screens/product_details_screen.dart' = ''
  'lib/screens/product_form_screen.dart' = ''
  'lib/screens/product_list_screen.dart' = ''
  'lib/screens/supplier_form_screen.dart' = ''
  'lib/widgets/entity_form_scaffold.dart' = ''
}

Write-Host '1/7  Исправляю все 13 замечаний анализатора...' -ForegroundColor Cyan
foreach ($Entry in $Payload.GetEnumerator()) {
  $RelativePath = $Entry.Key
  $Target = Join-Path $Root $RelativePath
  if (-not (Test-Path $Target)) {
    throw "Не найден файл: $RelativePath"
  }
  $Backup = Join-Path $BackupRoot $RelativePath
  $BackupDir = Split-Path -Parent $Backup
  New-Item -ItemType Directory -Force -Path $BackupDir | Out-Null
  Copy-Item $Target $Backup -Force
  [IO.File]::WriteAllBytes($Target, [Convert]::FromBase64String($Entry.Value))
  Write-Host "  OK  $RelativePath"
}

Write-Host '2/7  Обновляю зависимости...' -ForegroundColor Cyan
& flutter pub get
if ($LASTEXITCODE -ne 0) { throw "flutter pub get завершился с кодом $LASTEXITCODE" }

Write-Host '3/7  Форматирую весь Dart-код...' -ForegroundColor Cyan
& dart format lib test
if ($LASTEXITCODE -ne 0) { throw "dart format завершился с кодом $LASTEXITCODE" }

Write-Host '4/7  Проверяю форматирование...' -ForegroundColor Cyan
& dart format --set-exit-if-changed lib test
if ($LASTEXITCODE -ne 0) { throw "Проверка dart format завершилась с кодом $LASTEXITCODE" }

Write-Host '5/7  Запускаю flutter analyze...' -ForegroundColor Cyan
& flutter analyze
if ($LASTEXITCODE -ne 0) {
  Write-Host "ОСТАНОВКА: analyze нашёл другие проблемы. Исходные 7 файлов сохранены в $BackupRoot" -ForegroundColor Red
  exit $LASTEXITCODE
}

Write-Host '6/7  Запускаю flutter test...' -ForegroundColor Cyan
& flutter test
if ($LASTEXITCODE -ne 0) {
  Write-Host "ОСТАНОВКА: тесты не прошли. Исходные 7 файлов сохранены в $BackupRoot" -ForegroundColor Red
  exit $LASTEXITCODE
}

Write-Host '7/7  Коммичу и отправляю исправления в GitHub...' -ForegroundColor Cyan
& git add .
if ($LASTEXITCODE -ne 0) { throw 'git add завершился ошибкой' }

& git diff --cached --quiet
$DiffCode = $LASTEXITCODE
if ($DiffCode -eq 1) {
  & git commit -m 'Fix analyzer issues for Practical 6'
  if ($LASTEXITCODE -ne 0) { throw 'git commit завершился ошибкой' }
} elseif ($DiffCode -ne 0) {
  throw "git diff завершился с кодом $DiffCode"
} else {
  Write-Host '  Изменений для нового коммита нет.'
}

& git push
if ($LASTEXITCODE -ne 0) { throw 'git push завершился ошибкой' }

Write-Host ''
Write-Host 'ГОТОВО.' -ForegroundColor Green
Write-Host 'Все 13 замечаний исправлены; format, analyze и test прошли; изменения отправлены на GitHub.' -ForegroundColor Green
Write-Host "Резервная копия исходных 7 файлов: $BackupRoot" -ForegroundColor DarkGray